import json, html
from collections import Counter,defaultdict
from pathlib import Path
o=Path(__file__).resolve().parents[1]/'outputs/keyword_site_analysis_20260911'; d=json.loads((o/'site_keywords.json').read_text())
def theme(k):
 q=k.lower()
 if any(x in q for x in ('calculator','analyzer','planner','generator','checker')): return '计算器和分析工具'
 if any(x in q for x in ('game','minecraft','pokemon','football','fifa','steam','roblox')): return '游戏辅助和数据工具'
 if any(x in q for x in ('download','mp3','video','audio','pdf','image','png')): return '图片、音频、视频处理'
 if any(x in q for x in ('font','template','icon','wallpaper','logo')): return '字体、模板和素材'
 if any(x in q for x in ('meaning','what is','wiki','list','guide')): return '内容解释和资料查询'
 return '其他可产品化需求'
g=defaultdict(list)
for x in d:g[theme(str(x.get('keyword',''))) ].append(x)
def tr(c): return ''.join(f'<tr><td>{html.escape(str(k))}</td><td>{v:,}</td><td>{v/len(d)*100:.1f}%</td></tr>' for k,v in c.most_common())
def bars(c): return ''.join(f'<div class="bar"><span>{html.escape(str(k))}</span><i style="width:{max(2,v/max(c.values())*100):.1f}%"></i><b>{v:,}</b></div>' for k,v in c.most_common())
theme_rows=''.join(f'<tr><td>{k}</td><td>{len(v):,}</td><td>{sum(float(x.get("volume") or 0) for x in v):,.0f}</td><td>{sum(float(x.get("volume") or 0) for x in v)/len(v):,.0f}</td><td>{sum(float(x.get("kd") or 0) for x in v)/len(v):.1f}</td><td>{sum(float(x.get("cpc") or 0) for x in v)/len(v):.2f}</td><td>{max(v,key=lambda x:float(x.get("volume") or 0)).get("keyword")}</td></tr>' for k,v in sorted(g.items(),key=lambda z:-len(z[1])))
source=Counter(x.get('provider','未知') for x in d); site=Counter(x.get('site_type','未知') for x in d); pri=Counter(x.get('priority','未知') for x in d)
H='''<!doctype html><meta charset="utf-8"><title>关键词建站机会分析报告 v3</title><style>body{font:15px Arial;background:#f3f6fa;color:#182536;margin:0}main{max-width:1200px;margin:24px auto;background:#fff;padding:36px}h2{border-left:5px solid #2463a6;padding-left:10px;margin-top:38px}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{background:#eaf3ff;padding:16px 22px;border-radius:8px;min-width:150px}.card b{font-size:26px}table{border-collapse:collapse;width:100%;margin:12px 0 26px}th{background:#173b63;color:#fff}td,th{padding:9px;border-bottom:1px solid #dce3ea;text-align:left}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.bar{display:flex;align-items:center;gap:8px;margin:9px 0}.bar span{width:150px}.bar i{height:18px;background:#4d8fd1;display:inline-block}.bar b{margin-left:auto}.box{background:#f8fafc;padding:16px;border-radius:8px}li{margin:8px 0}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><main>'''
H+=f'<h1>关键词建站机会分析报告</h1><p>分析日期：2026-09-11｜数据来源：Similarweb、Semrush｜市场：Global / US</p><div class=cards><div class=card>原始候选<br><b>15,936</b></div><div class=card>最终保留<br><b>{len(d):,}</b></div><div class=card>高优先级<br><b>{pri.get("高",0):,}</b></div></div><p class=box>过滤条件：搜索量 ≥ 5,000，CPC ≥ 0.01，KD 分档上限 30/45/60，排除明显敏感、品牌和版权风险词。</p><h2>一、核心结论</h2><p>当前候选重点集中在可以通过单页交付结果的工具、游戏数据和内容资源方向。优先从计算器、生成器、分析器和游戏查询工具中选择 MVP；素材和内容方向适合广告及程序化 SEO；下载和品牌相关方向先做风险复核。</p><h2>二、来源与优先级</h2><div class=grid><div><h3>来源数量</h3>{bars(source)}</div><div><h3>站点类型</h3>{bars(site)}<h3>优先级</h3>{bars(pri)}</div></div><h2>三、主题聚类真实统计</h2><table><tr><th>主题</th><th>词数</th><th>总搜索量</th><th>平均搜索量</th><th>平均KD</th><th>平均CPC</th><th>代表高流量词</th></tr>{theme_rows}</table><h2>四、主题建站方案</h2><div class=box><b>计算器和分析工具：</b>输入参数→计算/比较→解释结果；MVP 包含表单、结果卡片、复制分享和 FAQ；广告、订阅、付费导出。<br><br><b>游戏辅助和数据工具：</b>查询角色、装备、交易和进度；先做单游戏单场景数据库；广告、会员、赞助。<br><br><b>图片音频视频处理：</b>上传→转换/压缩→下载；批量处理和高级格式可做订阅；需核查版权。<br><br><b>字体模板和素材：</b>分类、预览、授权、下载；付费资源、联盟、广告。<br><br><b>内容解释和资料查询：</b>围绕“是什么、怎么用、完整列表”做专题集群；广告、赞助、线索获客。</div><h2>五、优先级与变现</h2><p><b>优先验证：</b>高搜索量、低 KD、需求明确、可单页承接且有 CPC 的方向。<br><b>次优先：</b>需要内容积累或差异化的模板、素材和资料主题。<br><b>暂缓：</b>品牌导航、敏感、版权下载、强品牌 SERP 或无清晰变现路径。</p><p>广告适合高流量内容和游戏资料；订阅适合分析、批量处理和高级报告；付费资源适合模板素材；联盟适合工具推荐；赞助和线索获客适合游戏及 B2B 方向。</p><h2>六、风险、限制与执行计划</h2><ul><li>Similarweb 与 Semrush 口径不同，搜索量不能简单相加。</li><li>KD、CPC 只是参考，必须人工复核 Google SERP。</li><li>品牌、下载器、字体、图片和游戏数据存在商标、版权或平台政策风险。</li><li>AI 判断是辅助，适合建站不等于保证流量或收入。</li></ul><ol><li>从高优先级主题选 5–10 个项目。</li><li>复核 SERP、域名、版权和变现路径。</li><li>制作 1–2 个 MVP，接入分析和转化追踪。</li><li>依据真实访问、留存和收入决定扩展。</li></ol></main>'
(o/'keyword_site_analysis_v3.html').write_text(H);print(len(H))
